/* Own-account editing. Email, role and workspace ownership cannot be edited. */
const profilePhoto={owner:'',path:'',url:''};
function portalAvatarHTML(name){return profilePhoto.owner===portal.user?.id&&profilePhoto.path===portal.profile?.avatar_path&&profilePhoto.url?`<img class="profile-avatar-image" src="${pe(profilePhoto.url)}" alt="Your profile photo">`:portalInitial(name)}
async function portalLoadAvatar(){const owner=portal.user?.id,path=portal.profile?.avatar_path||'';profilePhoto.owner=owner;profilePhoto.path=path;profilePhoto.url='';if(!owner||!path||!path.startsWith(owner+'/'))return;const r=await portal.client.storage.from('sigma-profile-photos').createSignedUrl(path,3600);if(!r.error&&portal.user?.id===owner&&portal.profile?.avatar_path===path)profilePhoto.url=r.data.signedUrl}
portalAccount=function(){if(!portal.user||!portal.profile)return;const p=portal.profile;modal('Your profile',`<form onsubmit="event.preventDefault();portalSaveProfile(this)"><div class="profile-photo-row"><div class="avatar profile-photo-large" data-photo-preview>${portalAvatarHTML(p.full_name)}</div><label class="profile-photo-picker">${I('file')}Change photo<input name="photo" type="file" aria-label="Choose profile photo" accept="image/jpeg,image/png,image/webp" onchange="portalPreviewPhoto(this)"><small>JPG, PNG or WebP · up to 5 MB</small></label></div><div class="formgrid"><label class="field full">Full name *<input name="fullName" required maxlength="100" autocomplete="name" value="${pe(p.full_name)}"></label><label class="field full">Email<input type="email" value="${pe(p.email)}" readonly><small>Your sign-in email</small></label><label class="field full">Phone number<input name="phone" type="tel" maxlength="20" autocomplete="tel" value="${pe(p.phone||'')}"></label><label class="field full">Address<textarea name="address" maxlength="500" rows="3" autocomplete="street-address">${pe(p.address||'')}</textarea></label></div><span class="badge">${pe(p.role)}</span><p class="portal-form-error" role="alert"></p><div class="modalfoot"><button type="button" onclick="closeModal()">Cancel</button><button class="primary" type="submit">Save profile</button></div></form>`)};
async function portalPreparePhoto(file){if(!file||!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error('Choose a JPG, PNG or WebP photo');if(file.size>5242880)throw Error('Choose a photo no larger than 5 MB');await PortalCore.validateFile(file);const bitmap=await createImageBitmap(file),scale=Math.min(1,512/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));try{const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob||blob.size>1048576)throw Error('Photo could not be prepared. Choose another image.');return blob}finally{bitmap.close();canvas.width=canvas.height=0}}
async function portalPreviewPhoto(input){const form=input.form,file=input.files[0],run=Symbol();form.photoRun=run;form.photoBlob=null;form.photoPending=false;const error=form.querySelector('.portal-form-error');error.textContent='';if(!file)return;form.photoPending=true;try{const blob=await portalPreparePhoto(file);if(!form.isConnected||form.photoRun!==run)return;form.photoBlob=blob;const url=URL.createObjectURL(blob),image=document.createElement('img');image.className='profile-avatar-image';image.alt='Selected profile photo';image.onload=()=>URL.revokeObjectURL(url);image.src=url;form.querySelector('[data-photo-preview]').replaceChildren(image)}catch(e){if(form.photoRun===run){input.value='';error.textContent=portalError(e)}}finally{if(form.photoRun===run)form.photoPending=false}}
async function portalSaveProfile(form){if(portal.busy||!portal.user)return;if(form.photoPending)return toast('Wait for the photo preview to finish.');const owner=portal.user.id,button=form.querySelector('button[type=submit]');portal.busy=true;button.disabled=true;form.querySelector('.portal-form-error').textContent='';try{const data=new FormData(form),name=String(data.get('fullName')||'').trim(),address=String(data.get('address')||'').trim(),rawPhone=String(data.get('phone')||'').trim(),phone=rawPhone?PortalCore.phone(rawPhone):'';if(!name||name.length>100||address.length>500)throw Error('Check your name and address');let path=portal.profile.avatar_path||'';if(form.photoBlob){path=owner+'/'+crypto.randomUUID()+'.jpg';const upload=await portal.client.storage.from('sigma-profile-photos').upload(path,form.photoBlob,{contentType:'image/jpeg',upsert:false,cacheControl:'0'});if(upload.error)throw upload.error}const result=await portal.client.rpc('sigma_save_profile',{p_name:name,p_phone:phone,p_address:address,p_avatar:path});if(result.error)throw result.error;if(portal.user?.id!==owner)return;portal.profile=Array.isArray(result.data)?result.data[0]:result.data;await portalLoadAvatar();closeModal();portalRender();portalNotify('Profile updated')}catch(e){if(form.isConnected)form.querySelector('.portal-form-error').textContent=portalError(e)}finally{portal.busy=false;button.disabled=false}}
